mapper.select:
SELECT DISTINCT a.id,a.goodsId,a.orderNo,a.shopName,a.imgUrl,a.goodsName,a.orderPrice,a.orderNumber,a.orderStatus,a.createtime,a.createId, (SELECT DISTINCT COUNT(a.id) FROM `order` a LEFT JOIN order_customer b ON a.orderNo = b.orderNo 1=1
AND b.orderNo = a.orderNo AND a.orderNo like "%"#{orderNo}"%"
AND a.orderNo = b.orderNo AND b.userId = #{userId}
AND a.del_flag = 0
) AS total FROM `order` a LEFT JOIN order_customer b ON a.orderNo = b.orderNo 1=1
AND b.orderNo = a.orderNo AND a.orderNo like "%"#{orderNo}"%"
AND a.orderNo = b.orderNo AND b.userId = #{userId}
AND a.del_flag = 0
ORDER BY a.id LIMIT #{pageStart},#{pageSize}

mapper.update:
UPDATE `order`
SET del_flag   = 1,
    updatetime = current_time,
    updateId   = #{updateId}
WHERE id = #{id}

mapper.delete:
DELETE
FROM order_customer
WHERE orderNo = #{orderNo}
  AND userId = #{userId}
  AND orderCustomer = #{orderCustomer}

mapper.select:
SELECT id, orderNo, userId, orderCustomer, orderTime
FROM order_customer
WHERE orderNo = #{orderNo}

mapper.update:
update shop_mall
SET stock = stock - #{orderNumber}
WHERE id = #{goodsId}

update `order`
SET orderNumber = orderNumber + #{number}
WHERE goodsId = #{goodsId}
  AND orderNo = #{orderNo}
